function GroceryDialog:OnFocus(focus)
    if focus then
        local node = self:GetGroceryNodeByGroceryType(self:GetSelectedGroceryType())
        if node and node.scr and node.scr.RefreshCurrencyBar then
            node.scr:RefreshCurrencyBar(self:GetSelectedGroceryType())
        end

        if self:GetFindId() and self._showFindView then
            CfUtils.RefreshTopGoods({})
        end
        
        -- set uiCamera state
        CfUtils.SetTopRightProjection(0)
        CfUtils.SetUICameraProjection(false, 26)
    end
end

function GroceryDialog:OnInitialize()
    return CoWaitDo(function()
        CfUtils.CookieSave(Constants.UICacheDataKeys.GROCERY_MAIN_OPENING, 1)
        -- save uiCamera state
        self.oldUICameraState_ = CfUtils.GetUICameraProjectionState()
        
        CriWareUtils.PlayMusicById("bgm_shop")
        self:InitHandler()
        self:InitData()
    end)
end

function GroceryDialog:OnFinalize()
    return CoWaitDo(function()
        CfUtils.CookieSave(Constants.UICacheDataKeys.GROCERY_MAIN_OPENING, 0)
        Events.RemoveListener(Constants.EventNames.GROCERY_REDPOINT_CHANGE, self.eventOnRedPointChangeCb_)
        Events.RemoveListener(Constants.EventNames.GROCERY_HOME_REFRESH, self._refreshDataEvent)
        Events.RemoveListener(Constants.EventNames.DailyUpdateData, self._dailyUpdateEvent)
        Events.RemoveListener(Constants.EventNames.GROCERY_STORE_REFRESH, self._refreshItemEvent)
        self:CloseFindTimer()

        if self._behaviourAction then
            self._behaviourAction.UpdateAction = nil
            self._behaviourAction = nil
        end

        -- 记录关闭界面时的所选页签
        local parameters = CfUtils.DialogSafeParameters(self.controller)
        parameters._recoverMainIndex = self:GetSelectedTab()
        parameters._recoverSubIndex  = self:GetSelectedSubTab()
        
        -- recover uiCamera state
        CfUtils.SetUICameraProjectionState(self.oldUICameraState_)
        -- 关闭定时器
        GroceryMgr:StopTimer()
        if not isNull(self._tabHandlerCo) then
            cs_coroutine.stop(self._tabHandlerCo)
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end)
end

function GroceryDialog:Update()
    if Utils.TouchCount() > 0 and (not self.__closing) then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local camera = UIModule.RootCanvas.canvas.worldCamera
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self.RetrievalTips, position, camera)
            local isActive = CfUtils.IsActive(self.RetrievalTips.gameObject)
            if isActive and not isInRect then
                CfUtils.SetActive(self.RetrievalTips, false)
            end
        end
    end
end
