---初始化搜索页签数据
function GroceryDialog:InitFindData()
    local goodsId = self:GetFindId()
    if not goodsId then return end
    
    local findData = {}
    local findId = self:GetFindId()
    local tabData = self:GetTabData()
    local subData = self:GetSubTabData()
    for i, v in ipairs(tabData) do
        if subData[i] then
            -- 存在子页签
            for _, sub in ipairs(subData[i]) do
                self:FindItem(sub.type, findId, findData)
            end
        else
            self:FindItem(v.type, findId, findData)
        end
    end
    
    self:SetFindData(findData)
    self:StartFindTimer()
end

---初始化主页签数据
function GroceryDialog:InitMainTabData()
    local tabData = {}
    for _, groceryType in ipairs(MainTabGroup) do
        local data = {}
        local conf = GroceryConstants.GroceryNodeConfigs[groceryType]
        local isUnlocked = false
        if conf.unlockId then
            isUnlocked = GameUtils.IsUnlockedBySystemTogId(conf.unlockId)
        else
            if conf.subTypes then
                local unlockSubTypes = self:CheckUnlockSubTypes(conf)
                if #unlockSubTypes > 0 then
                    isUnlocked = true
                end
            else
                -- 没任何配置认为默认解锁
                isUnlocked = true
            end
        end
        if isUnlocked then
            data = {
                name        = GroceryUtils.GetTabNameByGroceryType(groceryType),
                bgPath      = conf.iconPath,
                type        = groceryType,
                func        = Bind(self, self.GroceryTabOnClickHandler),
                redPointFun = Bind(self, self.GroceryTabOnRedPointHandler),
            }
            table.insert(tabData, data)
        end
    end

    self:SetTabData(tabData)
end

---@param conf GroceryConstants.GroceryNodeConfig
function GroceryDialog:CheckUnlockSubTypes(conf)
    local unlockSubTypes = {}
    for _, subType in ipairs(conf and conf.subTypes or {}) do
        local isUnlocked = false
        ---@type GroceryConstants.GroceryNodeConfig
        local subConf = GroceryConstants.GroceryNodeConfigs[subType] or {}
        if subConf then
            -- 有解锁id，就按照解锁id判断；没有解锁id就是默认要显示出来
            if subConf.unlockId then
                isUnlocked = GameUtils.IsUnlockedBySystemTogId(subConf.unlockId)
            else
                isUnlocked = true
            end
        end
        if isUnlocked then
            table.insert(unlockSubTypes, subType)
        end
    end
    return unlockSubTypes
end

---初始化子页签数据
function GroceryDialog:InitSubTabData()
    self:InitEquipmentSubTabData()
end

-- 初始化装备商店子页签
function GroceryDialog:InitEquipmentSubTabData()
    local equipmentConf  = GroceryConstants.GroceryNodeConfigs[GroceryConstants.GroceryType.Equipment] or {}
    local unlockSubTypes = self:CheckUnlockSubTypes(equipmentConf)
    if #unlockSubTypes <= 0 then return end

    local equipDataMap   = {}
    for _, equipmentData in ipairs(GroceryMgr:GetEquipmentData()) do
        equipDataMap[tostring(equipmentData.poolType)] = equipmentData
    end
    local equipSubTabData = {}
    for _, subType in ipairs(unlockSubTypes) do
        ---@type GroceryConstants.GroceryNodeConfig
        local subConf   = GroceryConstants.GroceryNodeConfigs[subType] or {}
        local equipData = equipDataMap[tostring(subConf.poolType)] or {}
        local subData   = {
            name        = equipData.poolName,
            func        = Bind(self, self.GroceryTabOnClickHandler),
            type        = GroceryConstants.EquipmentPoolTypeToGroceryType[checkInt(equipData.poolType)],
            redPointFun = Bind(self, self.GroceryTabOnRedPointHandler),
        }
        table.insert(equipSubTabData, subData)
    end
    self:SetSubTabDataByGroceryType(GroceryConstants.GroceryType.Equipment, equipSubTabData)
end

---初始化选中的页签
function GroceryDialog:InitSelectedTab()
    if self:GetFindId() then
        self:SetSelectedTab(FindViewTabIndex)
        return
    end
    local initGroceryType = nil
    if self._parameter.groceryType then
        initGroceryType = self._parameter.groceryType
        self._parameter.groceryType = nil
    else
        initGroceryType = CfUtils.CookieLoad(Constants.UICacheDataKeys.GROCERY_LAST_SELECT_TYPE)
        CfUtils.CookieSave(Constants.UICacheDataKeys.GROCERY_LAST_SELECT_TYPE, nil)
    end
    if initGroceryType then
        local idx, subIdx = self:GetTabIndexByGroceryType(initGroceryType)
        if not idx then return end
        self:SetSelectedTab(idx)
        self:SetSelectedSubTab(subIdx)
    else
        -- 读取关闭界面时的所选页签
        local recoverMainIndex = checkInt(self._parameter._recoverMainIndex)
        local recoverSubIndex  = checkInt(self._parameter._recoverSubIndex)
        self._parameter._recoverMainIndex = nil
        self._parameter._recoverSubIndex = nil
        if recoverMainIndex > 0 then
            self:SetSelectedTab(recoverMainIndex)
        end
        if recoverSubIndex > 0 then
            self:SetSelectedSubTab(recoverSubIndex)
        end
    end
end
