function GroceryDialog:DoGroceryTabOnClickHandler(data)
    local parentType = nil
    local curType = self:GetSelectedGroceryType()
    ---@type GroceryConstants.GroceryNodeConfig
    local config = GroceryConstants.GroceryNodeConfigs[curType]
    if config and config.parent then
        parentType = config.parent
    end

    if self:GetForceRefresh() then
        self:SetForceRefresh(false)
    else
        if curType == data.type then return end
        
        local curNode = self:GetGroceryNodeByGroceryType(parentType or curType)
        if curNode then
            -- 隐藏当前node
            self:SetCanvasEnabled(curNode, false)
        end
    end
    
    if data.isChild then
        self:SetSelectedSubTab(data.__ind)
        self:ShowGroceryNode(data.type)
    else
        self:SetSelectedTab(data.__ind)
        -- 判断页签是否有子页签
        if not self:CheckSubTabByGroceryType(data.type) then
            self:SetSelectedSubTab(0)
            self:ShowGroceryNode(data.type)
        end
    end

    if self:GetFindId() and self._showFindView then
        self._showFindView = false
        self:SetCanvasEnabled(self.UIContainer, true)
        CfUtils.SetActive(self.RetrievalView, false)
    end
end

---搜索页签点击回调处理
function GroceryDialog:FindTabOnClickHandler()
    if self._showFindView then return end

    local parentType = nil
    local curType = self:GetSelectedGroceryType()
    ---@type GroceryConstants.GroceryNodeConfig
    local config = GroceryConstants.GroceryNodeConfigs[curType]
    if config and config.parent then
        parentType = config.parent
    end
    
    local curNode = self:GetGroceryNodeByGroceryType(parentType or curType)
    if curNode then
        -- 隐藏当前node
        self:SetCanvasEnabled(curNode, false)
    end
    
    self._showFindView = true
    self:SetSelectedTab(FindViewTabIndex)
    self:RefreshGroceryList()
    self:SetCanvasEnabled(self.UIContainer, false)
    CfUtils.SetActive(self.RetrievalView, true)
    self:RefreshFindView()
    CfUtils.RefreshTopGoods({})
end

---页签红点处理
function GroceryDialog:GroceryTabOnRedPointHandler(data)
    local redPoint = 0
    ---@type GroceryConstants.GroceryNodeConfig
    local config = GroceryConstants.GroceryNodeConfigs[data.type]
    if config and config.redPoint then
        redPoint = checkInt(redPointCom:GetNodeNum(config.redPoint))
    end
    return redPoint > 0
end

