---搜索页面列表刷新
---@param idx number
function GroceryDialog:OnGetItemByIndex(cell, idx)
    if idx < 0 then return nil end

    ---@type GroceryBaseNodeListCell
    local nodeScr = CfUtils.GetLuaScr(cell, GroceryConstants.ScrPath.GroceryBaseNodeListCell)
    if isNull(nodeScr) then return nil end

    local index = idx + 1
    local data = self:GetFindData()[index]
    nodeScr:SetClickCallback(Bind(self, self.FindViewCellOnClickHandler))
    nodeScr:RefreshCell(data, index)
    
    return cell
end

