---刷新UI
function GroceryDialog:RefreshUI()
    CfUtils.SetActive(self.RetrievalTab, self:GetFindId() and true or false)
    self:SetForceRefresh(true)
    self:RefreshGroceryList()
    
    if self:GetFindId() and self._showFindView then
        self:SetCanvasEnabled(self.UIContainer, false)
        CfUtils.SetActive(self.RetrievalView, true)
        self:RefreshFindView()
        return 
    end
    self:SetCanvasEnabled(self.UIContainer, true)
    CfUtils.SetActive(self.RetrievalView, false)
end

---刷新查找页面
function GroceryDialog:RefreshFindView()
    local data = self:GetFindData()
    if not self.RetrievalScrollView.mLoopListView.IsListViewInit then
        self.RetrievalScrollView:InitListView(#data, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.RetrievalScrollView, #data)
    end

    local findId = self:GetFindId()
    local goodsVo = GoodsConfMgr:GetGoodsVoById(findId)
    local desc = ''
    if #data == 0 then
        desc = localize("未找到包含<color=#30ffee>【_name_】</color>的商品", {_name_ = goodsVo.name})
    else
        desc = localize("已为您找到包含<color=#30ffee>【_name_】</color>的商品:", {_name_ = goodsVo.name})
    end
    CfUtils.FillText(self.RetrievalTextDesc, desc)
    CfUtils.FillText(self.RetrievalTipsTextDesc, localize("自动检索范围：杂货铺中已解锁的商店。"))
end

---刷新杂货铺列表
function GroceryDialog:RefreshGroceryList()
    self.leftTabExpandEnv_ = CfUtils.GetLuaScr(self.CommonTabToggleLeftExpand, GroceryConstants.ScrPath.CommonTabToggleLeftExpand)
    if isNull(self.leftTabExpandEnv_) then return end
    
    self.leftTabExpandEnv_:Refresh(
        self:GetTabData(),
        self:GetSubTabData(),
        self:GetSelectedTab(),
        self:GetSelectedSubTab()
    )
end

---显示一个商店页面
---@param groceryType GroceryConstants.GroceryType
function GroceryDialog:ShowGroceryNode(groceryType)
    if not groceryType then return end
    local parentType = nil

    ---@type GroceryConstants.GroceryNodeConfig
    local config = GroceryConstants.GroceryNodeConfigs[groceryType]
    if config and config.parent then
        parentType = config.parent
    end

    local nodes = self:GetGroceryNodes()
    if nodes[groceryType] or nodes[parentType] then
        self:RefreshGroceryNode(groceryType, parentType)
    else
        self:CreateGroceryNode(groceryType, parentType)
    end
end

---刷新商店页面
---@param groceryType GroceryConstants.GroceryType
---@param parentType GroceryConstants.GroceryType | nil
function GroceryDialog:RefreshGroceryNode(groceryType, parentType)
    local refreshType = parentType or groceryType

    local currencyList = nil
    local node = self:GetGroceryNodeByGroceryType(refreshType)
    if node then
        self:SetCanvasEnabled(node, true)

        if not isNull(node.scr) then
            if node.scr.Refresh then
                node.scr:Refresh(groceryType)
            end
            if node.scr.RefreshCurrencyBar then
                node.scr:RefreshCurrencyBar(groceryType)
            else
                CfUtils.RefreshTopGoods({Constants.Currency.FreeDiamondId})
            end
        end
    end
end

---创建一个商店页面
---@param groceryType GroceryConstants.GroceryType
---@param parentType GroceryConstants.GroceryType | nil
function GroceryDialog:CreateGroceryNode(groceryType, parentType)
    CfUtils.StartCoroutineWithBlocker(function()
        xTry(function()
            local createType = parentType or groceryType

            ---@type GroceryConstants.GroceryNodeConfig
            local config = GroceryConstants.GroceryNodeConfigs[createType]
            if not config then return end

            local go = GameUtils.LoadBundleAsyncById(config.prefabId, self.UIContainer.gameObject, false)
            local scr = CfUtils.GetLuaScr(go, config.scrPath)
            local node = {
                go = go,
                scr = scr,
            }
            self:SetGroceryNodeByGroceryType(createType, node)
            self:RefreshGroceryNode(groceryType, parentType)
        end)
    end)
end

---检查页签是否存在子页签
---@param groceryType GroceryConstants.GroceryType
---@return boolean
function GroceryDialog:CheckSubTabByGroceryType(groceryType)
    local index = self:GetTabIndexByGroceryType(groceryType)
    if not index then return end
    
    local subTabData = self:GetSubTabData()
    return subTabData[index] and true or false
end

---根据杂货铺类型查找指定商品
---@param groceryType GroceryConstants.GroceryType
---@param goodsId integer 道具id
---@param itemList table 商品列表
function GroceryDialog:FindItem(groceryType, goodsId, itemList)
    local config = GroceryConstants.GroceryNodeConfigs
    if checkTable(config[groceryType]).dataKey then
        local storeData = GroceryMgr:GetGroceryDataByType(groceryType)
        for _, itemData in ipairs(checkTable(storeData.products)) do
            if checkInt(itemData.icon) == checkInt(goodsId) then
                local data = self:ConvertFindItemData(groceryType, itemData, storeData)
                table.insert(itemList, data)
            else
                if itemData.rewards then
                    for _, rewardData in ipairs(checkTable(itemData.rewards)) do
                        if rewardData.goodsId == goodsId then
                            local data = self:ConvertFindItemData(groceryType, itemData, storeData)
                            table.insert(itemList, data)
                            break
                        end
                    end
                end
            end
        end
    end
end

---转换查找道具数据
---@param groceryType GroceryConstants.GroceryType
---@param itemData table 商店道具数据
---@param storeData table 商店数据
function GroceryDialog:ConvertFindItemData(groceryType, itemData, storeData)
    local data = clone(itemData)
    if checkInt(storeData.nextRefreshLeftSeconds) > 0 then
        data.nextRefreshLeftSeconds = storeData.nextRefreshLeftSeconds
    end
    data.groceryType = groceryType

    if groceryType == GroceryConstants.GroceryType.SyncPVP then
        local rank = GroceryMgr:GetLadderData().segment
        if checkInt(rank) < checkInt(data.tab) then
            data.exLock = true
            data.exLockDesc = localize("_name1_段位达到_name2_解锁", {
                _name1_ = GroceryUtils.GetTabNameByGroceryType(groceryType), 
                _name2_ = GroceryConstants.SyncPVPTapTitle[checkInt(data.tab)]
            })
        end
    elseif groceryType == GroceryConstants.GroceryType.AsyncPVP then
        local groceryData = GroceryMgr:GetRegionalData()
        local unlockTab = groceryData.mallUnlockTab
        local rewards   = groceryData.mallBuyRewards
        if checkInt(unlockTab) < checkInt(data.tab) then
            local rewardsVo = CfUtils.GetCfVo(AutoIds.IdSetting3089, "StoreAsyncPVPRewardsVo", rewards[checkInt(data.tab) - 1].id)
            local goodsVo = GoodsConfMgr:GetGoodsVoById(itemData.prices[1].currency)
            data.exLock = true
            data.exLockDesc = localize("花费_num__name_解锁", {
                _num_  = rewardsVo.amount,
                _name_ = goodsVo.name
            })
        end
    elseif groceryType == GroceryConstants.GroceryType.Club then
        local tab = data.tab
        if not GameUtils.IsUnlockedBySystemTogId(GroceryConstants.ClubUnlockConfig[tab]) then
            data.exLock = true
            data.exLockDesc = GameUtils.GetUnlockDescrBySystemTogId(GroceryConstants.ClubUnlockConfig[tab])
        end
    end
    return data
end

---开启搜索定时器
function GroceryDialog:StartFindTimer()
    self:CloseFindTimer()
    CfUtils.TimerAppend(Constants.TimerName.GroceryDialogFindTimer, 1, function()
        for _, data in ipairs(self:GetFindData()) do
            if checkInt(data.nextRefreshLeftSeconds) > 0 then
                data.nextRefreshLeftSeconds = data.nextRefreshLeftSeconds - 1
            end
        end
    end)
end

---关闭搜索定时器
function GroceryDialog:CloseFindTimer()
    CfUtils.TimerRemove(Constants.TimerName.GroceryDialogFindTimer)
end
