end

---获取tabData
function GroceryDialog:GetTabData()
    return self._tabData
end

---设置subTabData
function GroceryDialog:SetSubTabData(subTabData)
    self._subTabData = checkTable(subTabData)
end

---通过GroceryType设置tabData
---@param groceryType GroceryConstants.GroceryType 
function GroceryDialog:SetSubTabDataByGroceryType(groceryType, data)
    local subTabData = self:GetSubTabData()
    local index = self:GetTabIndexByGroceryType(groceryType)
    if not index then return end
    
    subTabData[index] = data
end

---获取subTabData
function GroceryDialog:GetSubTabData()
    return self._subTabData
end

