    return self._selectedSubTab
end

---获取杂货铺节点
function GroceryDialog:GetGroceryNodes()
    return self._groceryNodes
end

---通过杂货铺类型获取杂货铺节点
---@param groceryType GroceryConstants.GroceryType
function GroceryDialog:SetGroceryNodeByGroceryType(groceryType, node)
    local groceryNodes = self:GetGroceryNodes()
    groceryNodes[groceryType] = node
end

---通过杂货铺类型获取杂货铺节点
---@param groceryType GroceryConstants.GroceryType
function GroceryDialog:GetGroceryNodeByGroceryType(groceryType)
    local groceryNodes = self:GetGroceryNodes()
    return groceryNodes[groceryType]
end

---通过杂货铺类型获取页签索引
---@return integer, integer 主页签索引，子页签索引
function GroceryDialog:GetTabIndexByGroceryType(groceryType)
    local tabData = self:GetTabData()
    local subTabData = self:GetSubTabData()
    for idx, conf in ipairs(tabData) do
        if subTabData[idx] then
            for subIdx, subConf in ipairs(subTabData[idx]) do
                if subConf.type == groceryType then
                    return idx, subIdx
                end
            end
        else
            if conf.type == groceryType then
                return idx
            end
        end
    end
end

---获取选中的商店类型
---@return GroceryConstants.GroceryType
function GroceryDialog:GetSelectedGroceryType()
    local tabIdx = self:GetSelectedTab()
    local subTabData = self:GetSubTabData()
    if subTabData[tabIdx] then
        local subTabIdx = self:GetSelectedSubTab()
        local subDataList = checkTable(subTabData[tabIdx])
        local subData = checkTable(subDataList[subTabIdx])
        return subData.type
    end

    local tabData = self:GetTabData()
    return checkTable(tabData[tabIdx]).type
end

---设置canvas状态
function GroceryDialog:SetCanvasEnabled(node, enabled)
    if isNull(checkTable(node).go) then return end

    CfUtils.SetCanvasEnabled(node.go, enabled)

    if node.scr and node.scr.SetEnabled then
        node.scr:SetEnabled(enabled)
    end
end

